def compute(vars):
    cash = vars["v1"]
    total = vars["v2"]

    if total == 0:
        return None

    portion_percent = (cash / total) * 100
    result = round(portion_percent)

    return {
        "value": result,
        "trace": {
            "cash_portion": cash,
            "total_purchase_price": total,
            "portion_percent": portion_percent,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
